<template>
  <div class="container">
    <div class="logo">
      <el-menu-icon><img class="logo-icon" src="@/assets/icon/kafei.png" alt="" /></el-menu-icon>
      <span class="logo-title">咖啡管理系统</span>
    </div>
    <div class="menu-wrapper">
      <el-menu
        background-color="transparent"
        text-color="#ffffff"
        :default-active="activeIndex"
        @select="handleSelect"
      >
        <el-menu-item v-for="item in menuList" :key="item.index" :index="item.index">
          <el-icon><img class="menu-icon" :src="item.icon" alt="" /></el-icon>
          <span>{{ item.name }}</span>
        </el-menu-item>
      </el-menu>
    </div>
    <div class="user-info">
      <div class="avatar">A</div>
      <div class="user-detail">
        <div class="user-name">管理员</div>
        <div class="user-role">超级管理员</div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref } from 'vue'
import { useRouter, useRoute } from 'vue-router'

const router = useRouter()
const route = useRoute()

// 当前选中的菜单索引（根据当前路由初始化并保持同步）
const activeIndex = ref('1')
const routeMap = {
  '/dashboard': '1',
  '/order': '2',
  '/goods': '3',
  '/shop': '4',
  '/user': '5',
  '/member': '6',
  '/coupon': '7',
  '/activity': '8',
  '/feedback': '9',
  '/system': '10',
}
activeIndex.value = routeMap[route.path] || '1'

// 菜单列表
const menuList = [
  { index: '1', name: '数据概览', path: '/dashboard', icon: require('@/assets/icon/shujugailan.png') },
  { index: '2', name: '订单管理', path: '/order', icon: require('@/assets/icon/ddguanli.png') },
  { index: '3', name: '商品管理', path: '/goods', icon: require('@/assets/icon/shangpinguanli.png') },
  { index: '4', name: '门店管理', path: '/shop', icon: require('@/assets/icon/mendianguanli.png') },
  { index: '5', name: '用户管理', path: '/user', icon: require('@/assets/icon/yonghuguanli.png') },
  { index: '6', name: '会员管理', path: '/member', icon: require('@/assets/icon/huiyuanguanli-copy.png') },
  { index: '7', name: '优惠券管理', path: '/coupon', icon: require('@/assets/icon/youhuiquanguanli.png') },
  { index: '8', name: '营销活动', path: '/activity', icon: require('@/assets/icon/activity.png') },
  { index: '9', name: '留言反馈', path: '/feedback', icon: require('@/assets/icon/feedback.png') },
  { index: '10', name: '系统设置', path: '/system', icon: require('@/assets/icon/settings.png') },
]
// 处理菜单点击事件，切换到对应页面
const handleSelect = (key) => {
  const item = menuList.find((m) => m.index === key)
  if (item) {
    router.push(item.path)
  }
}
// 监听路由变化，高亮当前菜单
router.afterEach((to) => {
  activeIndex.value = routeMap[to.path] || '1'
})
</script>
